{"file_path":"src/snapshot.js","content":"/** The digest snapshot format `plan` reads. */

import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot line, carrying the 1-based line it was read from. */
export class SnapshotError extends Error {
  /**
   * @param {number} line - the 1-based line within the snapshot.
   * @param {string} message - the message the specification words, without the `error: <snapshot>: line N: ` prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Parse a snapshot's text into its recorded digests.
 * @param {string} text - the whole snapshot file.
 * @returns {Map<string, string>} the digest recorded for each path.
 * @throws {SnapshotError} on a malformed line.
 */
export function parseSnapshot(text) {
  const digests = new Map()
  for (const [index, raw] of splitLines(text).entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(line, 'expected <path> <digest>')
    const [path, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(line, `invalid digest ${digest}`)
    if (digests.has(path)) throw new SnapshotError(line, `path ${path} is recorded twice`)
    digests.set(path, digest)
  }
  return digests
}
"}

